// STEP 1 + STEP 8: normalize every source's raw items into a common topic shape,
// categorize into the 21 opportunity categories, tag a recency window, and score
// each topic on all 8 required dimensions (0-100).
const runId = $('Run Config').first().json.run_id;
const allInputs = $input.all();
const raw = [];

for (const item of allInputs) {
  const d = item.json;
  if (d.data && d.data.children) { // reddit
    for (const p of d.data.children) raw.push({ title: p.data.title, source: 'reddit', window: '24h', signal: p.data.score + p.data.num_comments });
  }
  if (d.data && d.data.posts && d.data.posts.edges) { // product hunt
    for (const p of d.data.posts.edges) raw.push({ title: `${p.node.name} — ${p.node.tagline}`, source: 'product_hunt', window: '24h', signal: p.node.votesCount });
  }
  if (d.hits) { // hacker news algolia
    for (const h of d.hits) raw.push({ title: h.title, source: 'hacker_news', window: '7d', signal: h.points || 0 });
  }
  if (d.items && Array.isArray(d.items) && d.items[0] && d.items[0].full_name) { // github search repos
    for (const r of d.items) raw.push({ title: `${r.full_name} — ${r.description || ''}`.slice(0, 200), source: 'github_trending', window: '7d', signal: r.stargazers_count });
  }
  if (d.related_queries) { // serpapi google trends
    for (const q of (d.related_queries.rising || []).concat(d.related_queries.top || [])) raw.push({ title: q.query, source: 'google_trends', window: '30d', signal: q.extracted_value || q.value || 50 });
  }
  if (d.articles) { // newsapi
    for (const a of d.articles) raw.push({ title: a.title, source: 'news', window: '30d', signal: 40 });
  }
  if (d.items && Array.isArray(d.items) && d.items[0] && d.items[0].snippet) { // youtube
    for (const v of d.items) raw.push({ title: v.snippet.title, source: 'youtube', window: '24h', signal: v.statistics ? Number(v.statistics.viewCount) / 50000 : 20 });
  }
}

const CATEGORY_KEYWORDS = {
  'Freelancing': /freelanc|upwork|fiverr|client work|gig/i,
  'Digital Products': /template|ebook|notion|canva|prompt pack|digital product|pdf guide/i,
  'AI Tools': /\bai\b|gpt|llm|chatbot|copilot|midjourney/i,
  'Side Hustles': /side hustle|side gig|extra income/i,
  'Passive Income Ideas': /passive income|dividend|royalt/i,
  'Online Business Ideas': /online business|ecommerce|dropship/i,
  'Remote Jobs': /remote job|work from home|wfh/i,
  'Tech Trends': /tech trend|technology|developer|programming/i,
  'Productivity Tools': /productivity|notion|todo|time management/i,
  'Startup Ideas': /startup|founder|venture|y combinator/i,
  'SaaS': /saas|subscription software|micro-saas/i,
  'Digital Marketing': /marketing|seo|content marketing|ads|growth hack/i,
  'No-Code Tools': /no.?code|low.?code|bubble|webflow|zapier/i,
  'AI Automation': /automation|workflow|n8n|zapier|make\.com/i,
  'Mobile Apps': /mobile app|ios app|android app|app store/i,
  'Website Ideas': /website|landing page|web design/i,
  'Student Income Opportunities': /student|college|university|intern/i,
  'Career Growth': /career|resume|job interview|promotion/i,
  'Business Trends': /business trend|market trend|industry/i,
  'Government Tech Trends': /government|gov.?tech|policy|regulation/i,
  'Viral Internet Trends': /viral|trending now|meme|going viral/i
};

function categorize(title) {
  for (const [cat, re] of Object.entries(CATEGORY_KEYWORDS)) if (re.test(title)) return cat;
  return 'Tech Trends';
}

const SOURCE_WEIGHT = { reddit: 1.1, product_hunt: 1.3, hacker_news: 1.15, github_trending: 1.1, google_trends: 1.3, news: 0.9, youtube: 1.15 };
const AUTOMATION_BOOST = /AI Tools|No-Code Tools|AI Automation|SaaS|Productivity Tools/;
const VIRAL_BOOST = /Viral Internet Trends|Side Hustles|Passive Income Ideas/;

const seen = new Map();
for (const t of raw) {
  if (!t.title || t.title.length < 6) continue;
  const key = t.title.toLowerCase().trim().slice(0, 80);
  const category = categorize(t.title);
  const weight = SOURCE_WEIGHT[t.source] || 1;
  const demand = Math.min(100, Math.round((Math.log10((t.signal || 1) + 1) * 28) * weight));
  const competition = Math.min(100, Math.max(10, Math.round(t.title.length > 70 ? 35 : 65)));
  const seo = Math.min(100, Math.round(demand * 0.6 + (100 - competition) * 0.4));
  const viral = Math.min(100, Math.round(demand * (VIRAL_BOOST.test(category) ? 1.25 : 0.9)));
  const automation = Math.min(100, Math.round(AUTOMATION_BOOST.test(category) ? 75 + Math.random() * 20 : 35 + Math.random() * 20));
  const difficulty = Math.min(100, Math.max(10, 100 - Math.round(demand * 0.3 + competition * 0.2)));
  const profitability = Math.min(100, Math.round(demand * 0.5 + (100 - competition) * 0.3 + seo * 0.2));
  const longterm = Math.min(100, Math.round((demand + (100 - competition) + automation) / 3));
  const overall = Math.round(demand * 0.22 + profitability * 0.2 + (100 - difficulty) * 0.1 + (100 - competition) * 0.15 + seo * 0.13 + viral * 0.1 + automation * 0.06 + longterm * 0.04);

  const row = {
    run_id: runId, title: t.title.slice(0, 250), category, source: t.source, window: t.window,
    demand_score: demand, profitability_score: profitability, difficulty_score: difficulty,
    competition_score: competition, seo_score: seo, viral_score: viral, automation_score: automation,
    longterm_score: longterm, overall_score: overall, status: 'candidate'
  };
  if (!seen.has(key) || seen.get(key).overall_score < overall) seen.set(key, row);
}

const ranked = Array.from(seen.values()).sort((a, b) => b.overall_score - a.overall_score).slice(0, 60);
return ranked.map(r => ({ json: r }));

// Keep the top-scoring topics per category (max 2 each, 20 total) as research seeds
// for the Digital Product and Freelancing research calls.
const items = $input.all().map(i => i.json);
const byCategory = {};
for (const t of items.sort((a, b) => b.overall_score - a.overall_score)) {
  byCategory[t.category] = byCategory[t.category] || [];
  if (byCategory[t.category].length < 2) byCategory[t.category].push(t);
}
const top = Object.values(byCategory).flat().slice(0, 20);
return [{ json: { run_id: items[0]?.run_id, topics: top } }];

